-- ============================================================================
-- A7 - COMPLETE LOAD
-- Supplier Invoice / Accounts Payable (3-way match: PO + GR + Invoice)
-- ============================================================================

-- FASE 1: DROP (cascade) - tabelas novas, esperado erro 'table not found' na 1a execucao, usar Skip All
DROP TABLE INDUSTRIAL_DATA.SUPPLIER_INVOICE_ITEM CASCADE;
DROP TABLE INDUSTRIAL_DATA.SUPPLIER_INVOICE CASCADE;
DROP TABLE INDUSTRIAL_DATA.PAYMENT_STATUS CASCADE;

-- FASE 2: CREATE CONFIG TABLE
CREATE TABLE INDUSTRIAL_DATA.PAYMENT_STATUS (STATUS_CODE NVARCHAR(10) NOT NULL PRIMARY KEY, STATUS_TEXT NVARCHAR(60) NOT NULL);

-- FASE 3: LOAD CONFIG DATA

-- FASE 4: CREATE SUPPLIER INVOICE HEADER + ITEM
CREATE TABLE INDUSTRIAL_DATA.SUPPLIER_INVOICE (
  INVOICE_ID NVARCHAR(10) NOT NULL PRIMARY KEY,
  EBELN NVARCHAR(10) NOT NULL,
  GR_ID NVARCHAR(10) NOT NULL,
  LIFNR NVARCHAR(10) NOT NULL,
  INVOICE_DATE DATE NOT NULL,
  DUE_DATE DATE NOT NULL,
  CURRENCY NVARCHAR(3) NOT NULL,
  TOTAL_AMOUNT DECIMAL(15, 2) NOT NULL,
  STATUS_CODE NVARCHAR(10) NOT NULL,
  FOREIGN KEY (EBELN) REFERENCES INDUSTRIAL_DATA.PURCHASE_ORDER(EBELN),
  FOREIGN KEY (GR_ID) REFERENCES INDUSTRIAL_DATA.GOODS_RECEIPT(GR_ID),
  FOREIGN KEY (LIFNR) REFERENCES INDUSTRIAL_DATA.SUPPLIER(LIFNR),
  FOREIGN KEY (CURRENCY) REFERENCES INDUSTRIAL_DATA.CURRENCY(WAERS),
  FOREIGN KEY (STATUS_CODE) REFERENCES INDUSTRIAL_DATA.PAYMENT_STATUS(STATUS_CODE),
  CHECK (TOTAL_AMOUNT >= 0)
);

CREATE TABLE INDUSTRIAL_DATA.SUPPLIER_INVOICE_ITEM (
  INVOICE_ITEM_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  INVOICE_ID NVARCHAR(10) NOT NULL,
  ITEM_NO INT NOT NULL,
  MATNR NVARCHAR(10) NOT NULL,
  QUANTITY_INVOICED DECIMAL(15, 2) NOT NULL,
  UNIT_PRICE DECIMAL(15, 2) NOT NULL,
  AMOUNT DECIMAL(15, 2) NOT NULL,
  FOREIGN KEY (INVOICE_ID) REFERENCES INDUSTRIAL_DATA.SUPPLIER_INVOICE(INVOICE_ID),
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  CHECK (QUANTITY_INVOICED >= 0),
  CHECK (UNIT_PRICE >= 0)
);

-- FASE 5: LOAD SUPPLIER INVOICE HEADERS (25 faturas, uma por recebimento)

-- FASE 6: LOAD SUPPLIER INVOICE ITEMS (116 itens, quantidade = recebido no A6)

-- FASE 7: VALIDACAO FINAL
SELECT 'A7 LOADED SUCCESSFULLY' FROM DUMMY;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.PAYMENT_STATUS;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.SUPPLIER_INVOICE;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.SUPPLIER_INVOICE_ITEM;
SELECT STATUS_CODE, COUNT(*) FROM INDUSTRIAL_DATA.SUPPLIER_INVOICE GROUP BY STATUS_CODE ORDER BY STATUS_CODE;
SELECT TOP 5 INVOICE_ID, EBELN, LIFNR, TOTAL_AMOUNT, STATUS_CODE FROM INDUSTRIAL_DATA.SUPPLIER_INVOICE ORDER BY TOTAL_AMOUNT DESC;
